import{_ as t,a as o,a3 as i,o as r}from"./chunks/framework.edeurCMZ.js";const u=JSON.parse('{"title":"Using GitHub apps for authenticating from eclccserver","description":"","frontmatter":{},"headers":[],"relativePath":"devdoc/githubapps.md","filePath":"devdoc/githubapps.md","lastUpdated":1788274664000}'),n={name:"devdoc/githubapps.md"};function s(a,e,l,c,p,g){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="using-github-apps-for-authenticating-from-eclccserver" tabindex="-1">Using GitHub apps for authenticating from eclccserver <a class="header-anchor" href="#using-github-apps-for-authenticating-from-eclccserver" aria-label="Permalink to &quot;Using GitHub apps for authenticating from eclccserver&quot;">​</a></h1><h2 id="creating-and-configuring-a-github-app-for-eclccserver" tabindex="-1">Creating and Configuring a GitHub App for eclccserver <a class="header-anchor" href="#creating-and-configuring-a-github-app-for-eclccserver" aria-label="Permalink to &quot;Creating and Configuring a GitHub App for eclccserver&quot;">​</a></h2><p>Here is a step-by-step guide to creating and configuring a GitHub App to use with the authentication mechanism.</p><h3 id="step-1-create-the-github-app" tabindex="-1">Step 1: Create the GitHub App <a class="header-anchor" href="#step-1-create-the-github-app" aria-label="Permalink to &quot;Step 1: Create the GitHub App&quot;">​</a></h3><ol><li>Go to your GitHub account (or Organization) <strong>Settings</strong>.</li><li>On the left sidebar, scroll down and click <strong>Developer settings</strong>.</li><li>Select <strong>GitHub Apps</strong> in the left sidebar, then click the <strong>New GitHub App</strong> button.</li><li>Fill out the <strong>Register new GitHub App</strong> form: <ul><li><strong>GitHub App name</strong>: Give it a recognizable name (e.g., <code>HPCC ECL Fetcher</code>).</li><li><strong>Homepage URL</strong>: You can use your organization&#39;s URL or the HPCC platform repository URL (this is just required by the form).</li><li><strong>Webhook</strong>: Uncheck the <strong>Active</strong> checkbox. (HPCC only needs to pull code; it doesn&#39;t need to listen for GitHub events).</li></ul></li><li>Set the <strong>Repository permissions</strong>: <ul><li>Under <strong>Repository permissions</strong>, find <strong>Contents</strong> and set the access to <strong>Read-only</strong>. (This gives the app permission to perform <code>git fetch</code> / <code>git clone</code>).</li></ul></li><li>Scroll to the bottom (<strong>Where can this GitHub App be installed?</strong>): <ul><li>Select <strong>Any account</strong> if you plan to fetch repositories owned by different organizations/users. Select <strong>Only on this account</strong> if you exclusively fetch repositories within your current organization.</li></ul></li><li>Click <strong>Create GitHub App</strong>.</li></ol><h3 id="step-2-gather-your-secrets" tabindex="-1">Step 2: Gather Your Secrets <a class="header-anchor" href="#step-2-gather-your-secrets" aria-label="Permalink to &quot;Step 2: Gather Your Secrets&quot;">​</a></h3><p>Immediately after creating the app, you will land on its settings page. You need to collect three items to populate your HPCC secrets configuration:</p><ol><li><strong>The App ID</strong> (<code>appid</code>): <ul><li>Look at the &quot;About&quot; section at the top of the page. Copy the <strong>App ID</strong>.</li></ul></li><li><strong>The Private Key</strong> (<code>appkey</code>): <ul><li>Scroll down to the <strong>Private keys</strong> section.</li><li>Click <strong>Generate a private key</strong>.</li><li>This will download a <code>.pem</code> file to your computer. The entire contents of this file (including the <code>-----BEGIN RSA PRIVATE KEY-----</code> and end tags) will be your <code>appkey</code> secret.</li></ul></li></ol><h3 id="step-3-install-the-app-get-the-installation-id" tabindex="-1">Step 3: Install the App &amp; Get the Installation ID <a class="header-anchor" href="#step-3-install-the-app-get-the-installation-id" aria-label="Permalink to &quot;Step 3: Install the App &amp; Get the Installation ID&quot;">​</a></h3><p>The App ID and Private Key alone are not enough; the app must be <em>installed</em> on the target account/repository to generate the <code>installationid</code>.</p><ol><li>While still on the App&#39;s settings page, click <strong>Install App</strong> on the left sidebar.</li><li>Click <strong>Install</strong> next to the user or organization account where the target ECL repositories live.</li><li>Choose whether to install it on <strong>All repositories</strong> or <strong>Only select repositories</strong>, then click <strong>Install</strong>.</li><li>You will be redirected to the installation settings page. Look at the URL in your browser&#39;s address bar. It will look like this: <code>https://github.com/settings/installations/12345678</code> or <code>https://github.com/organizations/YOUR_ORG/settings/installations/12345678</code></li><li>Copy the numeric value at the end of the URL (e.g., <code>12345678</code>). This is your <strong>Installation ID</strong> (<code>installationid</code>).</li></ol><h2 id="configuring-the-secrets-for-eclccserver" tabindex="-1">Configuring the secrets for eclccserver <a class="header-anchor" href="#configuring-the-secrets-for-eclccserver" aria-label="Permalink to &quot;Configuring the secrets for eclccserver&quot;">​</a></h2><ol><li><p>configure the git user name to be x-access-token</p></li><li><p>Create a secret category &quot;git&quot;, secret &quot;x-access-token&quot;</p></li><li><p>Place these three values highlighted above (<code>appid</code>, <code>appkey</code>, and <code>installationid</code>) into your HPCC secret.</p></li></ol>',13)])])}const d=t(n,[["render",s]]);export{u as __pageData,d as default};
